type SupplierHotel = {
  property: {
    code: string;
    name: string;
    category: string;
    location: { city: string; countryCode: string };
  };
};

type Hotel = {
  id: string;
  name: string;
  city: string;
  countryCode: string;
  starRating: number | null;
};

const ratingMap: Record<string, number> = {
  ONE_STAR: 1,
  TWO_STAR: 2,
  THREE_STAR: 3,
  FOUR_STAR: 4,
  FIVE_STAR: 5,
};

function mapHotel(p: SupplierHotel): Hotel {
  return {
    id: p.property.code,
    name: p.property.location.city,
    city: p.property.name,
    countryCode: p.property.location.countryCode,
    starRating: ratingMap[p.property.category] ?? null,
  };
}

type SupplierOffer = {
  offerId: string;
  rate: {
    board: string;
    refundability: string;
    amount: number;
    currency: string;
  };
};

type Offer = {
  id: string;
  mealPlan: 'room_only' | 'breakfast_included' | 'half_board' | 'full_board';
  cancellationPolicy: 'refundable' | 'non_refundable';
  price: { amount: number; currency: string };
};

const mealPlanMap: Record<string, Offer['mealPlan']> = {
  ROOM_ONLY: 'room_only',
  BREAKFAST: 'breakfast_included',
  HALFBOARD: 'half_board',
  FULLBOARD: 'full_board',
};

const cancellationMap: Record<string, Offer['cancellationPolicy']> = {
  REFUNDABLE: 'refundable',
  NONREFUNDABLE: 'non_refundable',
};

function mapOffer(p: SupplierOffer): Offer {
  return {
    id: p.offerId,
    mealPlan: mealPlanMap[p.rate.board] ?? 'room_only',
    cancellationPolicy: cancellationMap[p.rate.refundability] ?? 'refundable',
    price: { amount: p.rate.amount, currency: p.rate.currency },
  };
}

type SupplierTrip = {
  tripRef: string;
  itinerary: {
    legs: Array<{
      departure: { airport: { code: string; name: string }; time: string };
      arrival: { airport: { code: string; name: string }; time: string };
    }>;
  };
  quote: { total: { amount: number; currency: string } };
};

type Trip = {
  id: string;
  segments: Array<{
    origin: string;
    destination: string;
    departureTime: string;
    arrivalTime: string;
  }>;
  totalPrice: { amount: number; currency: string };
};

function mapTrip(p: SupplierTrip): Trip {
  return {
    id: p.tripRef,
    segments: p.itinerary.legs.map((leg) => ({
      origin: leg.departure.airport,
      destination: leg.arrival.airport.code,
      departureTime: leg.departure.time,
      arrivalTime: leg.arrival.time,
    })),
    totalPrice: {
      amount: p.quote.total.amount,
      currency: p.quote.total.currency,
    },
  };
}
